/**
 * Underwater adventuring (Of Ships and the Sea, chapters 5-10; owner's request 1.0.82). Tables and rule figures in
 * module/rules/underwater-tables.mjs (GENERATED by tools/build-underwater-tables.py, which quotes and regex-checks them).
 * An actor is underwater while it has the "Underwater" status (UNDERWATER_STATUS); its actor flag `ad2e.underwater`
 * { depth, air, freeAction, coldProtected, maxDepth, acclimated, breath, checks } holds the details the GM tool sets.
 * Sources (adnd2e.fandom.com): Combat Effects (OSS) rev 172759 ("Surface dwellers add 4 to their initiative rolls and
 * suffer a -4 penalty to their attack rolls when fighting underwater"; Underwater Combat proficiency "only add 2 ... -2";
 * "a ring of free action" negates them), Temperature (OSS) rev 172710 (below 300 feet: -2 attack and damage, +2
 * initiative unprotected), Movement - Underwater (OSS) rev 172850, Vision - Underwater (OSS) rev 172704, Communication
 * (OSS) rev 241755, Special Weapons (OSS) rev 172778, Casting Spells Underwater (OSS) rev 241756, Spells Allowed Underwater
 * (OSS) rev 172859, Underwater Alterations (OSS) rev 247403, Underwater Encounters (OSS) rev 173017, Swimming (PHB)
 * rev 144872 (holding one's breath).
 * Implementation choices: Table 43 (maximum functioning depth) is a picture on the wiki, so only the text's figures
 * (human 400 feet, dwarf 600) are defaults and the GM sets other creatures' depth on the actor; weapons are matched to
 * Table 44 by the words of their names; the attack dialog offers the penalties as ticked boxes (the GM can untick them);
 * specialization bonuses are not removed automatically (the box notes it); "air" (an airy water sphere or similar)
 * removes the combat penalties and lets casters speak.
 */
import { UNDERWATER } from "./rules/underwater-tables.mjs";
import { ad2eDialog } from "./dialogs.mjs";

export { UNDERWATER };
export const UNDERWATER_STATUS = { id: "ad2e-underwater", name: "AD2E.Underwater.Status", img: "systems/ad2e/styles/icons/underwater.svg" };
export const WATERS = ["clear", "turbid", "murky"];
export const SURFACES = ["clearday", "overcast", "stormy", "moonlitnight", "moonlessnight"];
const i18n = (k, d) => (d ? game.i18n.format(k, d) : game.i18n.localize(k));
const esc = v => foundry.utils.escapeHTML?.(String(v ?? "")) ?? String(v ?? "");
const words = s => String(s ?? "").toLowerCase().replace(/\(all types\)/g, "").replace(/[^a-z0-9]+/g, " ").trim().split(/\s+/).filter(Boolean);

/**
 * Tables 39-41 (pure): what a surface dweller sees at a depth. The surface condition moves down one row per depth step
 * (clear water 50 feet, turbid 35, murky 10); artificial light like sunlight sets Clear Day, weaker light Overcast. Clear
 * water past 250 feet reads as turbid water on a moonless night; beyond the last row (or turbid 175, murky 50 feet) nothing
 * is seen. Returns the row ({ movement, spotted, type, id, detail } in yards) or null (blind).
 */
export function visionAt(water, surface, depth = 0, { light = "" } = {}) {
  const w = WATERS.includes(water) ? water : "clear";
  const steps = UNDERWATER.visionSteps[w];
  if (light === "sun") return UNDERWATER.vision[w][0];
  let i = SURFACES.indexOf(surface);
  if (i < 0) i = 0;
  const d = Math.max(Number(depth) || 0, 0);
  if (light === "torch") return UNDERWATER.vision[w][1];
  if (w === "clear" && d > steps.blind) return d > steps.blind + steps.extra ? null : UNDERWATER.vision.turbid[4];
  if (w !== "clear" && d > steps.blind) return null;
  i += Math.floor(d / steps.step);
  if (i > 4) return w === "clear" && d <= steps.blind + steps.extra ? UNDERWATER.vision.turbid[4] : null;
  return UNDERWATER.vision[w][i];
}

/** Infravision underwater (pure): a quarter of its range. */
export const infravisionRange = feet => Math.floor((Number(feet) || 0) * UNDERWATER.infravision);

/** Swimming rate in yards per round (pure; 0 = cannot swim): nonproficient a third of land movement x 5 (unencumbered only), proficient half (light load a third). No metal armour. */
export function swimRate(land, { proficient = false, encumbrance = "none", metalArmor = false } = {}) {
  if (metalArmor) return 0;
  const m = UNDERWATER.movement.swim;
  const enc = encumbrance || "none";
  if (!proficient) return enc === "none" ? Math.floor((Number(land) || 0) * m.nonproficient) * m.yardsPer : 0;
  if (enc === "none") return Math.floor((Number(land) || 0) * m.proficient) * m.yardsPer;
  if (enc === "light") return Math.floor((Number(land) || 0) * m.proficientLight) * m.yardsPer;
  return 0;
}

/** Walking on the bottom (pure): a third of land movement x 5 yards. */
export const walkRate = land => Math.floor((Number(land) || 0) * UNDERWATER.movement.walk) * UNDERWATER.movement.swim.yardsPer;

/** Sinking feet per round (pure): 10, or 40 in metal armour or with more than 30 lb of gear. */
export const sinkRate = ({ metalArmor = false, gearLb = 0 } = {}) => (metalArmor || gearLb > UNDERWATER.movement.sink.heavyLb ? UNDERWATER.movement.sink.heavy : UNDERWATER.movement.sink.normal);

/** Depth Units beyond the maximum depth (pure): 601-1199 feet for a 600-foot dwarf is one, 1200-1799 two. */
export function depthUnits(depth, maxDepth) {
  const d = Number(depth) || 0;
  const m = Number(maxDepth) || 0;
  if (!m || d <= m) return 0;
  return Math.floor(d / m);
}

/** Crushing damage for a failed depth save (pure): 4d10 plus 1d10 per Depth Unit. */
export const depthDamage = units => `${UNDERWATER.depth.damage} + ${units}${UNDERWATER.depth.perUnit.slice(1)}`;

/** Penalty to initiative, attacks, saves and checks for functioning beyond the maximum depth (pure): -1 per Depth Unit beyond the first. */
export const depthPenalty = units => Math.min(-(Math.max(units, 1) - 1), 0) || 0;

/** Default maximum depth for a character's race (only the figures the text gives; pure). */
export function defaultMaxDepth(actor) {
  if (actor?.type !== "character") return null;
  const race = String(actor.system?.raceInfo?.raceItem?.system?.identifier ?? actor.system?.raceInfo?.raceItem?.name ?? "").toLowerCase();
  return UNDERWATER.depth.known[race] ?? (race.includes("dwar") ? UNDERWATER.depth.known.dwarf : race.includes("human") ? UNDERWATER.depth.known.human : null);
}

/** Holding breath (pure): a third of Constitution in rounds (rounded up), halved exerting, halved without a good gulp; at least 1. */
export function breathRounds(con, { exerting = false, noGulp = false } = {}) {
  let r = Math.ceil((Number(con) || 0) * UNDERWATER.breath.conFraction);
  if (exerting) r = Math.ceil(r * UNDERWATER.breath.exerting);
  if (noGulp) r = Math.ceil(r * UNDERWATER.breath.noGulp);
  return Math.max(r, UNDERWATER.breath.minimum);
}

/** The Constitution check penalty for the nth check beyond the held breath (pure): 0, -2, -4 ... */
export const breathCheckPenalty = n => (Math.max(n, 1) - 1) * UNDERWATER.breath.checkStep;

/**
 * Combat modifiers underwater (pure): attack and initiative (-4/+4; Underwater Combat proficiency -2/+2; free action or
 * air: none), cold below 300 feet without protection (-2 attack and damage, +2 initiative), depth beyond the maximum.
 */
export function combatMods({ proficient = false, freeAction = false, air = false, depth = 0, coldProtected = false, maxDepth = null } = {}) {
  const c = UNDERWATER.combat;
  const free = freeAction || air;
  const base = free ? { attack: 0, initiative: 0 } : proficient ? { ...c.proficient } : { attack: c.attack, initiative: c.initiative };
  const cold = !coldProtected && (Number(depth) || 0) > c.cold.depth;
  const units = depthUnits(depth, maxDepth);
  const dp = depthPenalty(units);
  return { base, cold: cold ? { attack: c.cold.attack, damage: c.cold.damage, initiative: c.cold.initiative } : null, depth: units > 1 ? dp : 0,
    attack: base.attack + (cold ? c.cold.attack : 0) + (units > 1 ? dp : 0), initiative: base.initiative + (cold ? c.cold.initiative : 0) - (units > 1 ? dp : 0),
    damage: cold ? c.cold.damage : 0 };
}

/**
 * Table 44 entry for a weapon item (pure): matched by the words of its name or identifier ("Long sword" -> "Sword, Long";
 * "Spear" -> "Spear, One-handed"; "Bow (All types)" covers any bow). null when the table does not list it.
 */
export function weaponEntry(item) {
  const names = [item?.name, item?.system?.identifier?.replace(/-/g, " ")].filter(Boolean).map(words);
  const same = (a, b) => a.length === b.length && a.every(x => b.includes(x));
  for (const n of names) {
    const exact = UNDERWATER.weapons.find(w => same(words(w.name), n));
    if (exact) return exact;
  }
  // "Spear", "Bastard sword": the table splits them into one- and two-handed rows; the one-handed row is used
  // (implementation choice; the GM reads the two-handed row from the source when the weapon is used so).
  const grip = new Set(["one", "two", "handed"]);
  for (const n of names) {
    const split = UNDERWATER.weapons.filter(w => { const ww = words(w.name); return n.every(x => ww.includes(x)) && ww.every(x => n.includes(x) || grip.has(x)); });
    const one = split.find(w => words(w.name).includes("one"));
    if (one) return one;
  }
  for (const n of names) {
    const all = UNDERWATER.weapons.find(w => /all types/i.test(w.name) && words(w.name).every(x => n.includes(x) || n.includes(`${x}s`)));
    if (all) return all;
    const sub = UNDERWATER.weapons.find(w => words(w.name).length > 1 && words(w.name).every(x => n.includes(x)));
    if (sub) return sub;
  }
  return null;
}

/** Spells that function underwater (pure): { listed, component, altered } for a spell's name and kind (wizard/priest). */
export function spellUnderwater(name, kind = "wizard") {
  const list = UNDERWATER.spells[kind === "priest" ? "priest" : "wizard"] ?? [];
  const n = String(name ?? "").toLowerCase().replace(/[’']/g, "'").trim();
  const hit = list.find(s => s.name.toLowerCase() === n);
  return hit ? { listed: true, component: hit.component, altered: hit.altered } : { listed: false, component: false, altered: false };
}

/** Table 46 entry for a component's name (pure; word match). */
export function componentEntry(name) {
  const n = words(name);
  return UNDERWATER.components.find(c => { const w = words(c.name); return w.length && w.every(x => n.includes(x)); }) ?? null;
}

/** Magical items underwater (pure): "none" (Table 47: does not work), "altered" (Table 48) or "". */
export function itemUnderwater(name) {
  const n = String(name ?? "").toLowerCase();
  const strip = s => s.toLowerCase().replace(/^(potion|wand|rod|staff|ring|scroll|elixir|oil|dust|philter) of /, "");
  if (UNDERWATER.items.none.some(x => x.toLowerCase() === n || strip(x) === n.replace(/^(potion|wand|rod|staff|ring|scroll|elixir|oil|dust|philter) of /, ""))) return "none";
  if (UNDERWATER.items.altered.some(x => x.toLowerCase() === n || strip(x) === n.replace(/^(potion|wand|rod|staff|ring|scroll|elixir|oil|dust|philter) of /, ""))) return "altered";
  return "";
}

/** An actor's underwater state, or null when it is not underwater. */
export function underwaterOf(actor) {
  if (!actor?.statuses?.has?.(UNDERWATER_STATUS.id)) return null;
  const f = actor.getFlag?.("ad2e", "underwater") ?? {};
  return { depth: Number(f.depth) || 0, air: !!f.air, freeAction: !!f.freeAction, coldProtected: !!f.coldProtected,
    maxDepth: Number(f.maxDepth) || defaultMaxDepth(actor), acclimated: Number(f.acclimated) || 0, breath: f.breath ?? null };
}

/** Whether a character has the Underwater Combat proficiency. */
export function underwaterProficient(actor) {
  return !!actor?.items?.some?.(i => i.type === "proficiency" && i.system?.identifier === "underwater-combat");
}

/**
 * Tick boxes for an attack dialog (AD2EActor#combatModFields): the attacker's underwater penalties, pre-ticked, and the
 * weapon's Table 44 note. Empty when the attacker is not underwater.
 */
export function attackFields(actor, item = null, { missile = false } = {}) {
  const uw = underwaterOf(actor);
  if (!uw) return "";
  const m = combatMods({ ...uw, proficient: underwaterProficient(actor) });
  const rows = [];
  if (m.base.attack) rows.push(`<label><input type="checkbox" name="uw-base" value="${m.base.attack}" checked> ${esc(i18n(underwaterProficient(actor) ? "AD2E.Underwater.AttackProficient" : "AD2E.Underwater.Attack"))} (${m.base.attack})</label>`);
  if (m.cold) rows.push(`<label><input type="checkbox" name="uw-cold" value="${m.cold.attack}" checked> ${esc(i18n("AD2E.Underwater.Cold"))} (${m.cold.attack})</label>`);
  if (m.depth) rows.push(`<label><input type="checkbox" name="uw-depth" value="${m.depth}" checked> ${esc(i18n("AD2E.Underwater.Depth"))} (${m.depth})</label>`);
  const notes = [];
  if (item?.type === "weapon") {
    const e = weaponEntry(item);
    if (e?.na) notes.push(i18n("AD2E.Underwater.WeaponNA", { name: item.name }));
    else if (e) notes.push(i18n("AD2E.Underwater.WeaponUse", { name: e.name, speed: e.speed, sm: e.damage[0], l: e.damage[1] }));
    if (/crossbow/i.test(item.name ?? "")) notes.push(i18n("AD2E.Underwater.Crossbow"));
    else if (missile && !e) notes.push(i18n("AD2E.Underwater.MissileNA"));
  }
  if (m.cold) notes.push(i18n("AD2E.Underwater.ColdDamage"));
  if (!uw.freeAction && !uw.air) notes.push(i18n("AD2E.Underwater.NoSpecialization"));
  return `<fieldset><legend>${esc(i18n("AD2E.Underwater.Legend", { depth: uw.depth }))}</legend><div class="ad2e-check-grid">${rows.join("")}</div>`
    + notes.map(n => `<p class="ad2e-note">${esc(n)}</p>`).join("") + "</fieldset>";
}

/** Sum and text of the ticked underwater boxes in a dialog form. */
export function attackPicked(form) {
  let sum = 0;
  const text = [];
  for (const k of ["base", "cold", "depth"]) {
    const box = form?.elements?.[`uw-${k}`];
    if (box?.checked) { sum += Number(box.value) || 0; text.push(`${i18n(`AD2E.Underwater.Short.${k}`)} ${box.value}`); }
  }
  return { sum, text: text.join("; ") };
}

/** Initiative term for an underwater combatant (AD2ECombatant / the initiative dialog): "+ N[Underwater]" or "". */
export function initiativeTerm(actor, { casting = false } = {}) {
  const uw = underwaterOf(actor);
  if (!uw) return "";
  const m = combatMods({ ...uw, proficient: underwaterProficient(actor) });
  // Casting: +4 for somatic gestures instead of the combat penalty ("not cumulative"; air or free action negate it).
  const base = casting ? (uw.air || uw.freeAction ? 0 : UNDERWATER.combat.spellInitiative) : m.base.initiative;
  const value = base + (m.cold ? m.cold.initiative : 0) - m.depth;
  return value ? ` + ${value}[${i18n("AD2E.Underwater.Status")}]` : "";
}

/**
 * Casting underwater: a note for the caster's owners and the GM (spell on the "functions underwater" list or not, altered,
 * component saves, verbal components needing air) with a button to roll Table 46 saves for the spell's materials.
 */
export async function castingNote(actor, spell) {
  const uw = underwaterOf(actor);
  if (!uw || !spell) return null;
  const kind = spell.system?.kind === "priest" ? "priest" : "wizard";
  const s = spellUnderwater(spell.name, kind);
  const lines = [i18n(s.listed ? (s.altered ? "AD2E.Underwater.SpellAltered" : "AD2E.Underwater.SpellWorks") : "AD2E.Underwater.SpellNotListed", { name: spell.name })];
  if (!uw.air && spell.system?.components?.verbal !== false) lines.push(i18n("AD2E.Underwater.Verbal"));
  const mats = (spell.system?.materials ?? []).map(m => m.name ?? m.label).filter(Boolean);
  const saves = mats.map(n => ({ name: n, entry: componentEntry(n) })).filter(x => x.entry);
  if (s.component || saves.length) lines.push(i18n("AD2E.Underwater.ComponentSaves"));
  const whisper = (game.users ?? []).filter(u => u.isGM || actor.testUserPermission?.(u, "OWNER")).map(u => u.id);
  return ChatMessage.implementation.create({ speaker: ChatMessage.getSpeaker({ actor }), whisper,
    content: lines.map(l => `<p>${esc(l)}</p>`).join("") + `<p class="ad2e-note"><a href="${esc(UNDERWATER.urls["Spells Allowed Underwater (OSS)"])}" target="_blank" rel="noopener">${esc(i18n("AD2E.Underwater.SpellLink"))}</a></p>`,
    flags: { ad2e: { componentSaves: saves.map(x => ({ name: x.name, save: x.entry.save, spoils: x.entry.spoils })) } } });
}

/** Roll Table 46 saves (d20 at or above the number; "spoils" fails at once). From the casting note's button. */
export async function rollComponentSaves(list) {
  const out = [];
  const rolls = [];
  for (const c of list ?? []) {
    if (c.spoils || c.save === null) { out.push(i18n("AD2E.Underwater.Spoils", { name: c.name })); continue; }
    const r = await new Roll("1d20").evaluate();
    rolls.push(r);
    out.push(i18n(r.total >= c.save ? "AD2E.Underwater.SaveOk" : "AD2E.Underwater.SaveFail", { name: c.name, roll: r.total, save: c.save }));
  }
  return ChatMessage.implementation.create({ content: out.map(l => `<p>${esc(l)}</p>`).join(""), rolls });
}

/** Button on a casting note (AD2EChatMessage#renderHTML). */
export function componentSaveButtons(message, html) {
  const list = message?.getFlag?.("ad2e", "componentSaves");
  if (!list?.length || !html?.querySelector) return;
  const box = document.createElement("div");
  box.className = "ad2e-damage-buttons";
  box.innerHTML = `<button type="button"><i class="fa-solid fa-droplet"></i> ${esc(i18n("AD2E.Underwater.RollSaves"))}</button>`;
  box.querySelector("button").addEventListener("click", ev => { ev.preventDefault(); return rollComponentSaves(list); });
  (html.querySelector(".message-content") ?? html).append(box);
}

/** A magical item used underwater: a note when Table 47 says it does not work or Table 48 that it changes. */
export async function itemNote(actor, item) {
  if (!underwaterOf(actor) || !item) return null;
  const k = itemUnderwater(item.name);
  if (!k) return null;
  return ChatMessage.implementation.create({ speaker: ChatMessage.getSpeaker({ actor }),
    content: `<p>${esc(i18n(k === "none" ? "AD2E.Underwater.ItemNone" : "AD2E.Underwater.ItemAltered", { name: item.name }))}</p>` });
}

/** Breath: one more round held; past the limit a Constitution check at a cumulative -2 (the GM tool's button). */
export async function breathRound(actor) {
  const uw = underwaterOf(actor);
  if (!uw) return null;
  const f = foundry.utils.deepClone(actor.getFlag("ad2e", "underwater") ?? {});
  const b = f.breath ?? { held: 0, limit: breathRounds(actor.system?.abilities?.con?.total ?? actor.system?.abilities?.con?.value ?? 10) };
  b.held += 1;
  let text = i18n("AD2E.Underwater.BreathHeld", { name: actor.name, n: b.held, limit: b.limit });
  let rolls = [];
  if (b.held > b.limit) {
    const con = actor.system?.abilities?.con?.total ?? 10;
    const pen = breathCheckPenalty(b.held - b.limit);
    const r = await new Roll("1d20").evaluate();
    rolls = [r];
    const ok = r.total <= con + pen;
    text = i18n(ok ? "AD2E.Underwater.BreathOk" : "AD2E.Underwater.BreathFail", { name: actor.name, roll: r.total, target: con + pen });
  }
  f.breath = b;
  await actor.setFlag("ad2e", "underwater", f);
  return ChatMessage.implementation.create({ speaker: ChatMessage.getSpeaker({ actor }), content: `<p>${esc(text)}</p>`, rolls });
}

/** Depth check (end of each turn beyond the maximum depth): save vs. paralyzation; failure: 4d10 + 1d10 per Depth Unit a round. */
export async function depthCheck(actor) {
  const uw = underwaterOf(actor);
  if (!uw?.maxDepth) return ui.notifications.warn(i18n("AD2E.Underwater.NoMaxDepth"));
  const units = depthUnits(uw.depth, uw.maxDepth);
  if (units <= uw.acclimated) return ui.notifications.info(i18n("AD2E.Underwater.WithinDepth", { name: actor.name }));
  await actor.rollSave?.("par", { quick: true });
  const ok = await ad2eDialog.confirm({ window: { title: i18n("AD2E.Underwater.DepthTitle") }, rejectClose: false,
    content: `<p>${esc(i18n("AD2E.Underwater.DepthAsk", { name: actor.name }))}</p>` });
  if (ok) {
    const f = foundry.utils.deepClone(actor.getFlag("ad2e", "underwater") ?? {});
    f.acclimated = units;
    await actor.setFlag("ad2e", "underwater", f);
    return ChatMessage.implementation.create({ speaker: ChatMessage.getSpeaker({ actor }), content: `<p>${esc(i18n("AD2E.Underwater.Acclimated", { name: actor.name, n: units }))}</p>` });
  }
  const r = await new Roll(depthDamage(units)).evaluate();
  return r.toMessage({ speaker: ChatMessage.getSpeaker({ actor }), flavor: i18n("AD2E.Underwater.Crushing", { name: actor.name }),
    flags: { ad2e: { damage: true, notAttack: true } } });
}

/** Freezing (optional rule): hourly Constitution check at -2 below 100 feet without protection; failure costs 1d4 Constitution (told to the GM). */
export async function freezingCheck(actor) {
  const uw = underwaterOf(actor);
  if (!uw || uw.coldProtected || uw.depth <= UNDERWATER.combat.freezing.depth) return ui.notifications.info(i18n("AD2E.Underwater.NotCold", { name: actor.name }));
  const con = actor.system?.abilities?.con?.total ?? 10;
  const r = await new Roll("1d20").evaluate();
  const ok = r.total <= con + UNDERWATER.combat.freezing.check;
  const loss = ok ? null : await new Roll(UNDERWATER.combat.freezing.loss).evaluate();
  return ChatMessage.implementation.create({ speaker: ChatMessage.getSpeaker({ actor }), rolls: [r, loss].filter(Boolean),
    content: `<p>${esc(i18n(ok ? "AD2E.Underwater.FreezeOk" : "AD2E.Underwater.FreezeFail", { name: actor.name, roll: r.total, target: con + UNDERWATER.combat.freezing.check, n: loss?.total }))}</p>` });
}

/** Status registration. Called in init. */
export function registerUnderwater() {
  const list = CONFIG.statusEffects;
  if (Array.isArray(list)) { if (!list.some(e => e.id === UNDERWATER_STATUS.id)) list.push({ ...UNDERWATER_STATUS }); }
  else if (list && !list[UNDERWATER_STATUS.id]) list[UNDERWATER_STATUS.id] = { ...UNDERWATER_STATUS };
}
